SELECT hd.hd_buy_potential, hd.hd_vehicle_count, CASE WHEN hd.hd_vehicle_count >= 2 THEN 'High Vehicle' ELSE 'Low Vehicle' END AS vehicle_category, COUNT(DISTINCT s.s_store_sk) AS store_count, AVG(ss.ss_sales_price) AS avg_sales_price, SUM(ss.ss_ext_sales_price) AS total_sales, RANK() OVER (ORDER BY SUM(ss.ss_ext_sales_price) DESC) AS sales_rank, DENSE_RANK() OVER (PARTITION BY hd.hd_buy_potential ORDER BY SUM(ss.ss_ext_sales_price) DESC) AS buy_potential_rank FROM store_sales ss JOIN household_demographics hd ON ss.ss_hdemo_sk = hd.hd_demo_sk JOIN store s ON ss.ss_store_sk = s.s_store_sk GROUP BY hd.hd_buy_potential, hd.hd_vehicle_count ORDER BY total_sales DESC
